using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "VolatileReactionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Orion/VolatileReactionCustomDescription", order = 0)]
public class VolatileReactionCustomDescription : GainTwoEffectsCustomDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		VolatileReactionAction volatileReactionAction = battleAction as VolatileReactionAction;
		return base.GetActionDescription(amountModified, battleAction) + "\n" + volatileReactionAction.ThirdEffectAction.GetActionDescription(GetAmountWithoutEquation(amountModified));
	}
}
